  var STRIP_RE = /[\s\u3000·•*_.~～\-—=+@#$%^&()（）\[\]【】{}|\\/::;；,，。、!！?？"'`「」『』<>《》]+/g;
  var LEXICON_DIR = node_path_default.join(node_path_default.dirname(fileURLToPath(import_meta.url)), "lexicon", "Vocabulary");
  function loadWords() {
    const set = new Set(HAND_WORDS);
    let fromFiles = 0;
    let files = 0;
    try {
      const names = node_fs_default.readdirSync(LEXICON_DIR).filter((n) => n.toLowerCase().endsWith(".txt")).sort();
      if (!names.length) throw new Error("目录无 txt 文件");
      for (const name of names) {
        for (const line of node_fs_default.readFileSync(node_path_default.join(LEXICON_DIR, name), "utf8").split(/\r?\n/)) {
          const w = line.trim().toLowerCase();
          if (!w || w.startsWith("#") || w.length < 2 || set.has(w)) continue;
          set.add(w);
          fromFiles++;
        }
        files++;
      }
      console.log("[moderation] 敏感词库已加载 " + set.size + " 词（Vocabulary 目录 " + files + " 个文件 " + fromFiles + " 词 + 手写补充 " + (set.size - fromFiles) + "）");
    } catch (e) {
      console.error("[moderation] 词库目录缺失/为空（" + LEXICON_DIR + "），仅用手写词表兜底：" + e.message);
    }
    return [...set];
  }
