          seed.stones,
          seed.totalStones,
          seed.dustTotal,
          seed.opens,
          seed.exp,
          seed.petTickets,
          seed.ascensions,
          seed.immortal,
          seed.power,
          seed.towerCleared,
          seed.stageCleared,
          seed.endlessBest,
          seed.wildMax,
          now
