      const wantBuy = !!(ctx.body && ctx.body.buy);
      const now = Date.now();
      const today = dayStr4(now);
      const saveRow = stmts.getSave.get(ctx.user.id);
      if (!saveRow) return sendJSON(res, 400, { error: "尚未创建云端存档" });
      const mirror = loadMirror2(saveRow.data);
